namespace sv_103cc19c6fa64094876c7ca9017dc438.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public event Action? OnChange;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId != value)
            {
                _currentWarehouseId = value;
                OnChange?.Invoke();
            }
        }
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Regional"),
        ("WH-003", "Warehouse C — West Regional"),
        ("WH-004", "Warehouse D — Cold Storage"),
    ];
}

namespace sv_103cc19c6fa64094876c7ca9017dc438.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Fired after <see cref="LatestLowStockCount"/> is updated so that
    /// every subscribed component can re-render — not just the polling caller.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches the latest count and notifies all subscribers.
    /// Called by the polling component; every other subscriber sees the update via the event.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LatestLowStockCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }
}

@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm"
        style="max-width: 280px;"
        @bind="SelectedWarehouse">
    @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private string SelectedWarehouse
    {
        get => WarehouseState.CurrentWarehouseId;
        set => WarehouseState.CurrentWarehouseId = value;
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LatestLowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.LatestLowStockCount</span>
}

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    private async Task OnAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.LatestLowStockCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LatestLowStockCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.LatestLowStockCount
                </p>
                <p class="text-muted mb-0">
                    items below minimum level at
                    <strong>@GetWarehouseName()</strong>
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted mb-0">@GetWarehouseName()</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">
                    <span class="badge bg-success">Active</span>
                </p>
                <p class="text-muted mb-0">Refreshing every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource _cts = new();

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch, then start the polling loop
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        while (await timer.WaitForNextTickAsync(ct))
        {
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        }
    }

    private async void OnWarehouseChanged()
    {
        // When the warehouse changes, refresh immediately
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        return Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
            ?? WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
        _cts.Cancel();
        _cts.Dispose();
    }
}

